1	#!/usr/bin/env node
2	import fs from 'node:fs';
3	import path from 'node:path';
4	import { createDocumentServer } from './server.js';
5	import { SnapshotError, Workspace } from './workspace.js';
6	
7	function demo() {
8	  const workspace = new Workspace();
9	  workspace.add({ id: 'welcome', title: '欢迎使用', body: '从 [[architecture]] 开始了解工作台。', tags: ['入门', 'Markdown'] });
10	  workspace.add({ id: 'architecture', title: '架构备忘', body: '本地优先的文档与双向链接基线。返回 [[welcome]]。', tags: ['架构', 'markdown'] });
11	  const result = {
12	    product: 'Lattice Workbench',
13	    documents: workspace.list(),
14	    search: workspace.search('markdown').map(({ id, title }) => ({ id, title })),
15	    relationships: Object.fromEntries(workspace.list().map(({ id }) => [id, workspace.links(id)])),
16	  };
17	  process.stdout.write(`${JSON.stringify(result, null, 2)}\n`);
18	}
19	
20	function readSnapshotFile(file) {
21	  try {
22	    return fs.readFileSync(file, 'utf8');
23	  } catch (error) {
24	    throw new SnapshotError('IO_ERROR', `cannot read snapshot file ${file}: ${error.message}`);
25	  }
26	}
27	
28	function atomicWrite(file, content) {
29	  const directory = path.dirname(path.resolve(file));
30	  const temp = path.join(directory, `.${path.basename(file)}.${process.pid}.tmp`);
31	  try {
32	    fs.writeFileSync(temp, content, 'utf8');
33	    fs.renameSync(temp, file);
34	  } catch (error) {
35	    try {
36	      fs.rmSync(temp, { force: true });
37	    } catch {
38	      // best-effort cleanup of the staging file
39	    }
40	    throw new SnapshotError('IO_ERROR', `cannot write snapshot file ${file}: ${error.message}`);
41	  }
42	}
43	
44	function parseMigrateArgs(args) {
45	  const positionals = [];
46	  let dryRun = false;
47	  for (const arg of args) {
48	    if (arg === '--dry-run') {
49	      dryRun = true;
50	    } else if (arg.startsWith('--')) {
51	      throw new SnapshotError('INVALID_OPTIONS', `unknown option: ${arg}`);
52	    } else {
53	      positionals.push(arg);
54	    }
55	  }
56	  if (positionals.length !== 4) {
57	    throw new SnapshotError('INVALID_OPTIONS', 'usage: migrate <base> <incoming> <output> <mode> [--dry-run]');
58	  }
59	  const [base, incoming, output, mode] = positionals;
60	  if (mode !== 'merge' && mode !== 'replace') {
61	    throw new SnapshotError('INVALID_OPTIONS', "mode must be 'merge' or 'replace'");
62	  }
63	  return { base, incoming, output, mode, dryRun };
64	}
65	
66	function migrate(args) {
67	  const { base, incoming, output, mode, dryRun } = parseMigrateArgs(args);
68	
69	  const workspace = new Workspace();
70	  workspace.importJSON(readSnapshotFile(base), { mode: 'replace' });
71	  const snapshot = workspace.importJSON(readSnapshotFile(incoming), { mode, dryRun });
72	
73	  const rendered = `${JSON.stringify(snapshot)}\n`;
74	  if (!dryRun) atomicWrite(output, rendered);
75	  process.stdout.write(rendered);
76	}
77	
78	function parsePort(value) {
79	  if (!/^\d+$/u.test(value)) {
80	    throw new SnapshotError('INVALID_OPTIONS', `invalid port: ${value}`);
81	  }
82	  const port = Number(value);
83	  if (port > 65535) {
84	    throw new SnapshotError('INVALID_OPTIONS', `invalid port: ${value}`);
85	  }
86	  return port;
87	}
88	
89	function parseServeArgs(args) {
90	  const positionals = [];
91	  let port = 3000;
92	  for (let index = 0; index < args.length; index += 1) {
93	    const arg = args[index];
94	    if (arg === '--port') {
95	      index += 1;
96	      if (index >= args.length) throw new SnapshotError('INVALID_OPTIONS', '--port requires a value');
97	      port = parsePort(args[index]);
98	    } else if (arg.startsWith('--port=')) {
99	      port = parsePort(arg.slice('--port='.length));
100	    } else if (arg.startsWith('--')) {
101	      throw new SnapshotError('INVALID_OPTIONS', `unknown option: ${arg}`);
102	    } else {
103	      positionals.push(arg);
104	    }
105	  }
106	  if (positionals.length !== 1) {
107	    throw new SnapshotError('INVALID_OPTIONS', 'usage: serve <snapshot> [--port <port>]');
108	  }
109	  return { file: positionals[0], port };
110	}
111	
112	function serve(args) {
113	  const { file, port } = parseServeArgs(args);
114	
115	  const workspace = new Workspace();
116	  if (fs.existsSync(file)) {
117	    // An unreadable or invalid snapshot is fatal; the file is left untouched.
118	    workspace.importJSON(readSnapshotFile(file), { mode: 'replace' });
119	  }
120	
121	  const server = createDocumentServer({
122	    workspace,
123	    save: (snapshot) => atomicWrite(file, `${JSON.stringify(snapshot)}\n`),
124	  });
125	  server.on('error', (error) => {
126	    reportError(new SnapshotError('IO_ERROR', `cannot serve ${file}: ${error.message}`));
127	  });
128	  server.listen(port, '127.0.0.1', () => {
129	    const address = server.address();
130	    process.stdout.write(`${JSON.stringify({ host: address.address, port: address.port })}\n`);
131	  });
132	}
133	
134	function reportError(error) {
135	  const payload = { code: error instanceof SnapshotError ? error.code : 'IO_ERROR' };
136	  if (typeof error.message === 'string') payload.message = error.message;
137	  if (Array.isArray(error.ids)) payload.ids = error.ids;
138	  process.stderr.write(`${JSON.stringify(payload)}\n`);
139	  process.exitCode = 1;
140	}
141	
142	const command = process.argv[2];
143	if (command === 'demo') {
144	  demo();
145	} else if (command === 'migrate') {
146	  try {
147	    migrate(process.argv.slice(3));
148	  } catch (error) {
149	    reportError(error);
150	  }
151	} else if (command === 'serve') {
152	  try {
153	    serve(process.argv.slice(3));
154	  } catch (error) {
155	    reportError(error);
156	  }
157	} else {
158	  process.stderr.write('Usage: node src/cli.js demo | node src/cli.js migrate <base> <incoming> <output> <mode> [--dry-run] | node src/cli.js serve <snapshot> [--port <port>]\n');
159	  process.exitCode = 1;
160	}
