    return s;
  })()],
];

for (const [label, data] of INVALID_SNAPSHOTS) {
  test(`invalid snapshot rejected: ${label}`, () => {
    const workspace = new Workspace();
    workspace.add({ id: 'existing', title: 'Existing', body: 'body text', tags: [] });
    const before = workspace.exportJSON();
