test('titles are only trimmed for uniqueness, not case-folded', () => {
  const snapshot = snapshotOf([]);
  snapshot.documents = [
    { id: 'a', title: 'Case', body: 'body text', tags: [] },
    { id: 'b', title: 'case', body: 'body text', tags: [] },
  ];
