95	function parseServeArgs(args) {
96	  const positionals = [];
97	  let port = 3000;
98	  let historyFile = null;
99	  for (let index = 0; index < args.length; index += 1) {
100	    const arg = args[index];
101	    if (arg === '--port') {
102	      index += 1;
103	      if (index >= args.length) throw new SnapshotError('INVALID_OPTIONS', '--port requires a value');
104	      port = parsePort(args[index]);
105	    } else if (arg.startsWith('--port=')) {
106	      port = parsePort(arg.slice('--port='.length));
107	    } else if (arg === '--history') {
108	      index += 1;
109	      if (index >= args.length || args[index] === '') throw new SnapshotError('INVALID_OPTIONS', '--history requires a value');
110	      historyFile = args[index];
111	    } else if (arg.startsWith('--history=')) {
112	      historyFile = arg.slice('--history='.length);
113	      if (historyFile === '') throw new SnapshotError('INVALID_OPTIONS', '--history requires a value');
114	    } else if (arg.startsWith('--')) {
115	      throw new SnapshotError('INVALID_OPTIONS', `unknown option: ${arg}`);
116	    } else {
117	      positionals.push(arg);
118	    }
119	  }
120	  if (positionals.length !== 1) {
121	    throw new SnapshotError('INVALID_OPTIONS', 'usage: serve <snapshot> [--port <port>] [--history <file>]');
122	  }
123	  if (historyFile !== null && path.resolve(positionals[0]) === path.resolve(historyFile)) {
124	    throw new SnapshotError('INVALID_OPTIONS', 'snapshot and history must be different files');
125	  }
126	  return { file: positionals[0], port, historyFile };
127	}
