129	function readText(file) {
130	  return fs.readFileSync(file, 'utf8');
131	}
132	
133	function writeStaging(file, content) {
134	  const temp = stagingPath(file);
135	  try {
136	    fs.writeFileSync(temp, content, 'utf8');
137	  } catch (error) {
138	    try {
139	      fs.rmSync(temp, { force: true });
140	    } catch {
141	      // best-effort cleanup
142	    }
143	    throw new SnapshotError('IO_ERROR', `cannot write file ${file}: ${error.message}`);
144	  }
145	  return temp;
146	}
147	
148	function removeQuiet(file) {
149	  try {
150	    fs.rmSync(file, { force: true });
151	  } catch {
152	    // best-effort cleanup
153	  }
154	}
155	
156	// Commits snapshot and history together. The history file is the commit
157	// marker: it is installed first and embeds the new snapshot checksum, so a
158	// kill between the two renames leaves a history the next startup replays to
159	// reconstruct the snapshot. A failed I/O step rolls the files back to the
160	// pre-commit state; the caller only swaps in-memory state after this returns.
161	function commitWithHistory(snapshotFile, historyFile, backupFile, snapshot, historySnapshot) {
162	  const snapshotText = `${JSON.stringify(snapshot)}\n`;
163	  const historyText = `${JSON.stringify(historySnapshot)}\n`;
164	  const snapshotTemp = writeStaging(snapshotFile, snapshotText);
165	  let historyTemp;
166	  try {
167	    historyTemp = writeStaging(historyFile, historyText);
168	  } catch (error) {
169	    removeQuiet(snapshotTemp);
170	    throw error;
171	  }
172	  const hadHistory = fs.existsSync(historyFile);
173	  try {
174	    if (hadHistory) fs.renameSync(historyFile, backupFile);
175	    fs.renameSync(historyTemp, historyFile);
176	  } catch (error) {
177	    if (hadHistory) {
178	      try {
179	        fs.renameSync(backupFile, historyFile);
180	      } catch {
181	        // startup recovery reconciles whatever remains
182	      }
183	    }
184	    removeQuiet(snapshotTemp);
185	    removeQuiet(historyTemp);
186	    throw new SnapshotError('IO_ERROR', `cannot write history file ${historyFile}: ${error.message}`);
187	  }
188	  try {
189	    fs.renameSync(snapshotTemp, snapshotFile);
190	  } catch (error) {
191	    try {
192	      if (hadHistory) {
193	        fs.renameSync(backupFile, historyFile);
194	      } else {
195	        fs.rmSync(historyFile, { force: true });
196	      }
197	    } catch {
198	      // startup recovery reconciles whatever remains
199	    }
200	    removeQuiet(historyTemp);
201	    throw new SnapshotError('IO_ERROR', `cannot write snapshot file ${snapshotFile}: ${error.message}`);
202	  }
203	  removeQuiet(backupFile);
204	}
205	
206	// Loads the snapshot/history pair and brings both to a single consistent
207	// state. Returns { workspace, ledger }. Throws a SnapshotError (IO_ERROR,
208	// INVALID_SNAPSHOT, or INVALID_HISTORY) on any unrecoverable problem; files
209	// are left untouched in that case.
210	function loadState(file, historyFile) {
211	  const workspace = new Workspace();
212	  let snapshot = null;
213	  if (fs.existsSync(file)) {
214	    const text = readSnapshotFile(file);
215	    workspace.importJSON(text, { mode: 'replace' });
216	    snapshot = workspace.exportJSON();
217	  } else {
218	    snapshot = workspace.exportJSON();
219	  }
220	
221	  if (historyFile === null) return { workspace, ledger: null };
222	
223	  const backupFile = `${historyFile}.bak`;
224	  // A kill between moving the old history aside and installing the new one
225	  // leaves only the backup; restore the pre-commit history before proceeding.
226	  if (!fs.existsSync(historyFile) && fs.existsSync(backupFile)) {
227	    try {
228	      fs.renameSync(backupFile, historyFile);
229	    } catch (error) {
230	      throw new SnapshotError('IO_ERROR', `cannot recover history file ${historyFile}: ${error.message}`);
231	    }
232	  }
233	
234	  if (!fs.existsSync(historyFile)) {
235	    // First run with a history file: revision 1 baselines the current content.
236	    // The file itself appears with the first successful write.
237	    return { workspace, ledger: HistoryStore.baseline(workspace.list()) };
238	  }
239	
240	  const ledger = loadHistoryFile(historyFile, readText);
241	  removeQuiet(backupFile);
242	  if (ledger.snapshotChecksum === snapshot.checksum) {
243	    return { workspace, ledger };
244	  }
245	
246	  // The files disagree: the history ledger is authoritative (it records every
247	  // acknowledged commit). Reconstruct the snapshot from its replay and install
248	  // it atomically.
249	  const recovered = snapshotFromDocuments(ledger.replayedDocuments().values());
250	  if (recovered.checksum !== ledger.snapshotChecksum) {
251	    throw new SnapshotError('INVALID_HISTORY', 'history cannot be reconciled to a consistent snapshot');
252	  }
253	  const recoveredWorkspace = new Workspace();
254	  recoveredWorkspace.importJSON(recovered, { mode: 'replace' });
255	  atomicWrite(file, `${JSON.stringify(recovered)}\n`);
256	  return { workspace: recoveredWorkspace, ledger };
257	}
