259	function serve(args) {
260	  const { file, port, historyFile } = parseServeArgs(args);
261	  const { workspace, ledger } = loadState(file, historyFile);
262	
263	  const backupFile = historyFile === null ? null : `${historyFile}.bak`;
264	  const server = createDocumentServer({
265	    workspace,
